// Bundles dist/ into a module the Worker can serve itself: worker/generated/site-files.js.
//
// Used only by wrangler.bundled.jsonc, for deploying from an environment where Cloudflare's
// static-asset upload cannot be used (it authenticates with a short-lived upload token that a
// credential-injecting proxy replaces). The intended setup is wrangler.jsonc with static assets;
// `npx wrangler deploy` from an ordinary machine uses that and needs none of this.
//
//   node scripts/build.js && node scripts/bundle-site.js
import { readFile, readdir, mkdir, writeFile } from 'node:fs/promises';
import { join, relative, extname } from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const dist = join(root, 'dist');
const TYPES = {
  '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml', '.txt': 'text/plain; charset=utf-8', '.xml': 'application/xml; charset=utf-8',
  '.json': 'application/json', '.png': 'image/png', '.woff2': 'font/woff2', '.webp': 'image/webp', '.avif': 'image/avif',
};
const BINARY = new Set(['.png', '.woff2', '.webp', '.avif']);

async function walk(d) {
  const out = [];
  for (const e of await readdir(d, { withFileTypes: true })) {
    const p = join(d, e.name);
    if (e.isDirectory()) out.push(...(await walk(p))); else out.push(p);
  }
  return out;
}

const files = {};
let headers = '';
for (const f of await walk(dist)) {
  const path = '/' + relative(dist, f).split('\\').join('/');
  const buf = await readFile(f);
  if (path === '/_headers') { headers = buf.toString('utf8'); continue; }
  const ext = extname(f);
  if (!TYPES[ext]) throw new Error(`No content type for ${path}`);
  files[path] = {
    type: TYPES[ext],
    etag: '"' + createHash('sha256').update(buf).digest('hex').slice(0, 20) + '"',
    ...(BINARY.has(ext) ? { b64: buf.toString('base64') } : { text: buf.toString('utf8') }),
  };
}
await mkdir(join(root, 'worker/generated'), { recursive: true });
await writeFile(join(root, 'worker/generated/site-files.js'),
  `// Generated by scripts/bundle-site.js from dist/. Do not edit.\nexport const FILES = ${JSON.stringify(files)};\nexport const HEADERS = ${JSON.stringify(headers)};\n`);
console.log(`Bundled ${Object.keys(files).length} files from dist/ into worker/generated/site-files.js`);
